import os,pty,sys,time,select,signal,resource,subprocess
d=subprocess.run([sys.executable,"_tools/kbmon.py","--split","--dry-run"],capture_output=True,text=True,env={k:v for k,v in os.environ.items() if k not in ("TMUX","WEZTERM_PANE","WT_SESSION")})
if d.returncode!=0 or "--interval" not in d.stdout:
    print("kbmon --split --dry-run prints no live-view command:",d.stdout[-200:],d.stderr[-200:]);sys.exit(1)
pid,fd=pty.fork()
if pid==0:
    os.execvp(sys.executable,[sys.executable,"_tools/kbmon.py","--interval","60"])
t=time.time()
while time.time()-t<30:
    r,_,_=select.select([fd],[],[],0.5)
    if r:
        try: os.read(fd,65536)
        except OSError: break
os.kill(pid,signal.SIGTERM); os.waitpid(pid,0)
u=resource.getrusage(resource.RUSAGE_CHILDREN); cpu=u.ru_utime+u.ru_stime
print("split live view cpu seconds in 30 s:",round(cpu,1)); sys.exit(0 if cpu<6 else 1)

